<template>
  <view class="workspace-page">
    <SiteHeader active="simulate" />
    <view class="workspace-shell">
      <view class="topline"><button class="back" @tap="backToList">← 返回模拟项目</button><button class="reset" @tap="confirmReset">重新开始</button></view>
      <view class="heading"><view><text class="eyebrow">AINPE PROJECT LAB / 项目工作台</text><text class="title">做一张能用的报名页。</text><text class="subtitle">一位老师需要收集活动报名。你来搭建、试用、发现问题，再亲手修好。</text></view><view class="version"><text class="version-label">当前作品</text><text class="version-num">V{{ state.revision }}</text></view></view>
      <view class="notice"><text>这是独立设计的模拟项目：老师、报名资料和测试结果均为虚构。不会调用 AI、注册账号、连接微信或发布小程序。</text></view>
      <view class="brief"><view class="avatar">林</view><view class="brief-content"><text class="brief-name">林老师 <text>· 模拟委托人</text></text><text class="brief-message">“我想做一场线下分享。大家填昵称后点报名，就能看到报名记录；<text class="highlight">昵称为空时不能报名。</text>麻烦先做个能试的版本。”</text></view></view>
      <view class="guide"><view><text class="guide-label">当前任务</text><text class="guide-text">{{ guide }}</text></view><text class="guide-status">{{ passed ? '已完成 ✓' : '进行中' }}</text></view>
      <view class="desk">
        <view class="editor pane"><view class="pane-head"><view><text class="pane-kicker">01 / BUILD</text><text class="pane-title">搭建你的页面</text></view><text class="pane-hint">点击组件添加或移除</text></view>
          <label class="field"><text class="field-label">页面标题</text><input class="input" :value="state.title" maxlength="20" @input="changeTitle" @blur="endTitleEdit" placeholder="给你的活动起个名字" /></label>
          <view class="section-title">组件库 <text>· 点击放进手机</text></view>
          <view class="components"><view v-for="part in parts" :key="part.id" class="component"><view><text class="component-name">{{part.name}}</text><text class="component-help">{{part.help}}</text></view><button :class="['tiny', state[part.id] ? 'added' : '']" @tap="togglePart(part.id)">{{state[part.id] ? '移除' : '＋ 添加'}}</button></view></view>
          <view class="section-title">给按钮连接动作</view><view class="rule-box"><view class="rule-line"><text class="node">报名按钮</text><text class="arrow">→</text><text class="node" :class="{empty:!state.connected}">{{state.connected?'写入报名记录':'尚未连接'}}</text></view><text class="small-copy">{{state.connected?'提交时会执行这条规则。':'把按钮连接到数据表，点击报名才会产生记录。'}}</text><button class="tiny" :disabled="!state.hasButton" @tap="toggleConnection">{{state.connected?'断开连接':'连接到报名记录 →'}}</button><text v-if="!state.hasButton" class="small-copy">先添加报名按钮。</text></view>
          <view class="section-title">在连接上增加规则</view><view class="rule-box"><view class="rule-line"><text class="node">报名按钮</text><text class="arrow">→</text><text class="node" :class="{empty:!state.required}">{{state.required?'检查昵称非空':'不检查昵称'}}</text><text class="arrow">→</text><text class="node" :class="{empty:!state.connected}">写入记录</text></view><text class="small-copy">{{state.required?'昵称为空时，会在写入前被拦截。':'目前输入为空时也可能写入。'}}</text><button class="tiny" :disabled="!state.connected || !state.hasInput" @tap="toggleRequired">{{state.required?'移除非空检查':'＋ 添加昵称非空检查'}}</button><text v-if="!state.connected || !state.hasInput" class="small-copy">先添加输入框，并连接报名按钮。</text></view>
        </view>
        <view class="preview pane"><view class="pane-head"><view><text class="pane-kicker">02 / TRY IT</text><text class="pane-title">亲手试试你的作品</text></view><text class="live">● 实时预览</text></view><text class="preview-caption">这部手机里的控件由你刚才的搭建决定。所有数据只存在当前设备。</text>
          <view class="phone"><view class="phone-bar"><text>9:41</text><text>···</text></view><view class="phone-body"><text class="phone-overline">线下交流 / MEET UP</text><text class="phone-title">{{state.title || '未命名活动'}}</text><text class="phone-copy">与同行见面，聊聊你的想法。</text><view class="phone-separator"></view><text v-if="state.hasInput" class="phone-label">你的昵称</text><input v-if="state.hasInput" class="phone-input" v-model="state.testName" maxlength="30" placeholder="输入模拟昵称" /><view v-else class="phone-placeholder">在左侧添加昵称输入框</view><button v-if="state.hasButton" class="phone-cta" @tap="submit">立即报名 →</button><view v-else class="phone-placeholder">在左侧添加报名按钮</view><text v-if="state.feedback" class="phone-feedback" :class="{bad:state.feedbackBad}">{{state.feedback}}</text><text class="phone-note">这是预览，不会发送真实报名</text></view></view>
          <view class="test-tip"><text class="test-tip-title">试运行建议</text><text>先不填昵称点报名，看看是否产生记录；再输入“林老师”试一次。更改规则后，两种情况都需要重测。</text></view>
        </view>
      </view>
      <view class="results-grid"><view class="pane data-pane"><view class="pane-head"><view><text class="pane-kicker">03 / DATA</text><text class="pane-title">模拟报名记录</text></view><button class="tiny" :disabled="state.rows.length===0" @tap="clearRows">清空测试记录</button></view><text class="small-copy">每点一次手机上的报名按钮，记录会根据你连接的规则实际变化。</text><view class="table-header"><text>昵称</text><text>来源</text></view><view v-if="!state.rows.length" class="empty-state">还没有记录。去手机预览里试一次。</view><view v-for="(row,index) in state.rows" :key="row.id" class="table-row"><text :class="{invalid:!row.name}">{{row.name || '（空昵称）'}}</text><text>预览提交 · {{index+1}}</text></view></view>
        <view class="pane log-pane"><view class="pane-head"><view><text class="pane-kicker">04 / TEST</text><text class="pane-title">运行记录与验收</text></view><text class="pane-hint">当前 V{{state.revision}}</text></view><view class="check-row"><text>空昵称应被拦截</text><text :class="checkClass(emptyStatus)">{{checkLabel(emptyStatus)}}</text></view><view class="check-row"><text>正常昵称能写入</text><text :class="checkClass(validStatus)">{{checkLabel(validStatus)}}</text></view><text class="small-copy">修改组件或规则会产生新版本；旧测试仍在日志中，需在当前版本重新测试。</text><view class="logs"><view v-if="!state.logs.length" class="empty-state">运行记录会显示在这里。</view><view v-for="entry in state.logs" :key="entry.id" class="log-line"><text :class="{invalid:entry.bad}">{{entry.message}}</text><text class="log-version">V{{entry.revision}} {{entry.revision!==state.revision?'· 已过期':''}}</text></view></view></view></view>
      <view v-if="passed" class="completion"><text class="completion-kicker">PROJECT COMPLETE / 模拟验收通过</text><text class="completion-title">这一次，你亲手修好了作品。</text><text>空昵称被拦截，正常昵称可以写入。你可以继续修改，也可以复制项目配置与测试结果。</text><view class="completion-actions"><button class="primary" @tap="copyProject">复制项目配置与测试结果</button><button class="secondary" @tap="backToList">看看其他模拟项目</button></view></view>
      <view v-else class="export-row"><button class="secondary" @tap="copyProject">复制当前项目配置与测试记录</button><text>可随时带走已有进度；模拟规则与数据不会被发布。</text></view>
      <SimCamp v-if="passed" />
    </view>
  <SiteFooter /></view>
</template>
<script setup>
import SiteFooter from '../../components/SiteFooter.vue';
import { computed, reactive, watch } from 'vue';
import SiteHeader from '../../components/SiteHeader.vue';
import SimCamp from './SimCamp.vue';
const KEY='ainpe:sim:workbench:v1';
const fresh=()=>({title:'老师的线下分享会',hasInput:false,hasButton:false,connected:false,required:false,testName:'',rows:[],logs:[],revision:1,emptyCheck:null,validCheck:null,feedback:'',feedbackBad:false});
let stored={};try{stored=uni.getStorageSync(KEY)||{}}catch{}
const state=reactive({...fresh(),...(stored&&typeof stored==='object'?stored:{})});
if(!Array.isArray(state.rows))state.rows=[];if(!Array.isArray(state.logs))state.logs=[];
watch(state,()=>{try{uni.setStorageSync(KEY,JSON.parse(JSON.stringify(state)))}catch{}},{deep:true});
const parts=[{id:'hasInput',name:'昵称输入框',help:'让用户填写一个昵称'},{id:'hasButton',name:'报名按钮',help:'点击后触发你设置的动作'}];
const emptyStatus=computed(()=>state.emptyCheck?.revision===state.revision?state.emptyCheck.status:'untested');
const validStatus=computed(()=>state.validCheck?.revision===state.revision?state.validCheck.status:'untested');
const passed=computed(()=>emptyStatus.value==='passed'&&validStatus.value==='passed');
const checkLabel=value=>value==='passed'?'通过':value==='failed'?'发现问题':'待测试';
const checkClass=value=>value==='passed'?'status-good':value==='failed'?'status-bad':'status-wait';
const guide=computed(()=>{if(!state.hasInput)return '先在组件库添加昵称输入框。';if(!state.hasButton)return '再添加一个报名按钮。';if(!state.connected)return '连接报名按钮和报名记录。';if(emptyStatus.value==='untested')return '留空昵称，点手机里的报名按钮，观察数据表。';if(emptyStatus.value==='failed')return '空昵称也被记录了。试着在连接上添加非空检查。';if(validStatus.value!=='passed')return '空昵称已被拦截。再输入一个模拟昵称测试正常路径。';return '两种测试都已通过。试试复制项目配置与测试结果。'});
function addLog(message,bad=false){state.logs.unshift({id:`${Date.now()}-${Math.random()}`,message,bad,revision:state.revision});state.logs=state.logs.slice(0,20)}
function revise(message){state.revision++;state.emptyCheck=null;state.validCheck=null;state.feedback='';state.feedbackBad=false;addLog(message)}
function togglePart(id){state[id]=!state[id];if(id==='hasButton'&&!state[id]){state.connected=false;state.required=false}if(id==='hasInput'&&!state[id])state.required=false;revise(`${state[id]?'添加':'移除'}了${id==='hasInput'?'昵称输入框':'报名按钮'}，请重新测试。`)}
function toggleConnection(){if(!state.hasButton)return;state.connected=!state.connected;if(!state.connected)state.required=false;revise(state.connected?'按钮已连接到报名记录。':'按钮连接已断开。')}
function toggleRequired(){if(!state.connected||!state.hasInput)return;state.required=!state.required;revise(state.required?'已加入昵称非空检查。':'已移除昵称非空检查。')}
let titleEditing=false;
function changeTitle(event){const title=event.detail.value;if(title!==state.title){state.title=title;if(!titleEditing){titleEditing=true;revise('页面标题已修改，请重新测试。')}}}
function endTitleEdit(){titleEditing=false}
function submit(){
  if(!state.hasButton)return;
  if(!state.connected){state.feedback='按钮尚未连接报名记录。';state.feedbackBad=true;addLog('点击报名：按钮没有连接动作。',true);return}
  if(!state.hasInput){state.feedback='页面没有昵称输入框，无法填写报名资料。';state.feedbackBad=true;addLog('点击报名：页面缺少昵称输入框。',true);return}
  const name=String(state.testName||'').trim();
  if(!name&&state.required){state.feedback='请输入昵称后再报名。';state.feedbackBad=true;state.emptyCheck={revision:state.revision,status:'passed'};addLog('空昵称测试：被非空规则拦截，没有写入记录。');return}
  state.rows.push({id:`${Date.now()}-${Math.random()}`,name});state.feedback=name?'已写入一条模拟报名记录。':'空昵称也被写入了，请检查规则。';state.feedbackBad=!name;
  if(!name){state.emptyCheck={revision:state.revision,status:'failed'};addLog('空昵称测试：空记录被写入，不符合委托要求。',true)}else{state.validCheck={revision:state.revision,status:'passed'};addLog(`正常昵称测试：${name} 已写入模拟记录。`)}
}
function clearRows(){uni.showModal({title:'清空模拟记录？',content:'只清空此设备上的试玩数据，不会修改作品配置或运行日志。',success:r=>{if(r.confirm)state.rows=[]}})}
function copyProject(){const rows=state.rows.map((row,i)=>`${i+1}. ${row.name||'（空昵称）'}`).join('\n')||'暂无';const data=`项目：${state.title}\n版本：V${state.revision}\n组件：${state.hasInput?'昵称输入框 ':''}${state.hasButton?'报名按钮':''}\n按钮动作：${state.connected?'写入报名记录':'未连接'}\n昵称非空检查：${state.required?'已添加':'未添加'}\n空昵称验收：${checkLabel(emptyStatus.value)}\n正常昵称验收：${checkLabel(validStatus.value)}\n模拟记录：\n${rows}\n\n本项目为本地模拟，不能直接发布。`;uni.setClipboardData({data})}
function confirmReset(){uni.showModal({title:'重新开始？',content:'将清除这台设备上的工作台作品及测试数据，其他模拟项目不受影响。',success:r=>{if(r.confirm)Object.assign(state,fresh())}})}
function backToList(){uni.navigateBack({fail:()=>uni.redirectTo({url:'/pages/simulate/index'})})}
</script>
<style src="./simulate.css"></style>
<style scoped>
