olor:#315a36;font-weight:700;margin-top:4px}.guide-status{font-size:12px;color:#66875c;white-space:nowrap}.desk,.results-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}.pane{background:#fff;border:1px solid #dfe8dc;border-radius:8px;padding:20px;min-width:0;box-sizing:border-box}.pane-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.pane-kicker,.pane-title{display:block}.pane-title{font-size:19px;font-weight:750;color:#214a34;margin-top:5px}.pane-hint,.live{font-size:11px;color:#829b7c}.live{color:#558a5f}.field{display:block;margin:16px 0}.field-label{font-size:12px;font-weight:700;display:block;margin-bottom:6px}.input{height:42px;box-sizing:border-box;width:100%;background:#f8faf7;border:1px solid #d9e5d7;border-radius:5px;padding:0 11px;font-size:14px}.section-title{font-weight:700;font-size:13px;margin:20px 0 9px}.section-title text{font-weight:400;font-size:11px;color:#8a9d86}.components{border:1px solid #e1ebde;border-radius:5px}.component{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 12px;border-bottom:1px solid #e8eee5}.component:last-child{border-bottom:0}.component-name,.component-help{display:block}.component-name{font-size:13px;font-weight:700}.component-help{font-size:11px;color:#8a9a88;margin-top:3px}.tiny{font-weight:700;white-space:nowrap}.tiny[disabled]{opacity:.45}.added{color:#6d846e;background:#fff}.rule-box{background:#f6f9f3;border:1px solid #e0eadd;border-radius:6px;padding:12px}.rule-box .tiny{margin-top:9px}.rule-line{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.node{font-size:12px;font-weight:700;background:#e1efd9;color:#315b39;padding:7px 9px;border-radius:4px}.node.empty{background:#fff;border:1px dashed #c7d4c3;color:#91a18c}.arrow{color:#8ba087}.small-copy{display:block;font-size:11px;line-height:1.65;color:#879985;margin-top:8px}.preview-caption{display:block;color:#80917f;font-size:12px;line-height:1.7;margin:12px 0}.phone{width:260px;max-width:100%;box-sizing:border-box;margin:18px auto 12px;background:#14271b;padding:9px;border-radius:25px;box-shadow:0 12px 24px #1d3d2720}.phone-bar{background:#fafcf8;border-radius:17px 17px 0 0;padding:10px 13px 3px;display:flex;justify-content:space-between;font-size:10px;color:#243e2b;font-weight:700}.phone-body{background:#fafcf8;border-radius:0 0 17px 17px;min-height:355px;padding:22px 17px;box-sizing:border-box}.phone-overline,.phone-title,.phone-copy,.phone-label,.phone-note,.phone-feedback{display:block}.phone-overline{font-size:9px;letter-spacing:1px;color:#75976a;font-weight:700}.phone-title{font-size:20px;font-weight:800;line-height:1.4;margin-top:10px;color:#173d2b}.phone-copy{font-size:11px;line-height:1.6;color:#819582;margin-top:8px}.phone-separator{height:1px;background:#e1eade;margin:18px 0}.phone-label{font-size:11px;font-weight:700;margin-bottom:7px}.phone-input{background:#fff;border:1px solid #d5e3d1;border-radius:4px;height:38px;padding:0 8px;box-sizing:border-box;font-size:12px}.phone-placeholder{font-size:11px;border:1px dashed #d6e2d2;color:#a6b3a2;border-radius:4px;padding:10px;margin-top:12px;text-align:center}.phone-cta{display:block;width:100%;margin:14px 0 0;background:#315d3c;color:#fff;border-radius:4px;padding:0 10px;line-height:39px;font-size:12px;font-weight:700}.phone-feedback{font-size:11px;line-height:1.6;color:#3f8c4c;margin-top:10px}.phone-feedback.bad{color:#b25c47}.phone-note{font-size:10px;color:#a2b0a1;margin-top:18px}.test-tip{background:#f6f9f2;padding:12px;border-radius:5px;font-size:12px;line-height:1.7;color:#738a72}.test-tip-title{display:block;font-weight:700;color:#456d48;margin-bottom:3px}.results-grid{margin-top:16px}.table-header,.table-row,.check-row{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid #edf1ea;font-size:12px}.table-header{font-size:11px;color:#8ca08c}.table-row text:last-child,.log-version{font-size:10px;color:#a0afa0}.invalid,.status-bad{color:#b75b47!important}.status-good{color:#37814b}.status-wait{color:#9daa9b}.empty-state{font-size:12px;color:#a0b09c;padding:17px 0}.logs{max-height:220px;overflow:auto}.log-line{display:flex;justify-content:space-between;gap:8px;padding:8px 0;font-size:11px;line-height:1.6;color:#718b75;border-bottom:1px solid #f0f3ed}.log-version{white-space:nowrap}.completion{margin-top:16px;padding:23px;border:1px solid #cce5bd;border-radius:8px;background:#eaf6df;font-size:13px;color:#638067;line-height:1.8}.completion-title{display:block;font-size:21px;font-weight:800;color:#245235;margin:6px 0}.completion-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:12px}.primary,.secondary{margin:0;padding:10px 14px;line-height:1.4;border-radius:5px;font-size:13px;font-weight:700}.primary{background:#25593a;color:#fff}.secondary{background:#f6faf3;color:#315e40;border:1px solid #d7e7d1}.export-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:17px 0;color:#8b9b88;font-size:11px;line-height:1.6}@media(max-width:700px){.workspace-shell{padding:16px 13px 35px}.title{font-size:26px}.desk,.results-grid{grid-template-columns:1fr}.pane{padding:17px}.heading{align-items:start}.version{min-width:42px}.brief{padding:15px}.guide-text{font-size:13px}.phone{margin:16px auto}.completion-actions{flex-direction:column}.completion-actions button{width:100%}.export-row{align-items:stretch}.export-row button{width:100%}}
</style>
